export type TranslationKey = keyof typeof translations.ne;

   
                              
                                                   
   
                                                  
                                                                  
                                                     
   
           
        
                                                     
                                                     
      
   
export function t(
  key: string,
  language: 'ne' | 'en' = 'ne',
  params?: Record<string, string | number>
): string {
  const keys = key.split('.');
  let value: string | NestedStringRecord = translations[language];

  for (const k of keys) {
    if (typeof value === 'object' && k in value) {
      value = value[k];
    } else {
                                                                                  
      console.warn(`Translation key not found: ${key}`);
      return key;
    }
  }

  if (typeof value === 'string') {
    if (!params) return value;
                                                    
    return Object.keys(params).reduce((acc, k) => {
      const v = String(params[k]);
      return acc.replace(new RegExp(`\\{${k}\\}`, 'g'), v);
    }, value);
  }

  return key;
}

   
                                                      
   
           
         
                                   
                                       
      
   
export function useTranslations(language: 'ne' | 'en' = 'ne') {
  const translate = useCallback(
    (key: string, params?: Record<string, string | number>) => t(key, language, params),
    [language],
  );

  return useMemo(
    () => ({
      t: translate,
      language,
    }),
    [translate, language],
  );
}

   
                                                               
   
           
        
                                                                
                                                                
      
   
export const validation = {
  minLength: (min: number) => {
    const template = t('validation.minLengthTemplate');
    return template.replace('{min}', min.toString());
  },
  maxLength: (max: number) => {
    const template = t('validation.maxLengthTemplate');
    return template.replace('{max}', max.toString());
  },
};
